import 'package:flutter/material.dart';
import '../services/cloud_config.dart';

class AdminLoginScreen extends StatefulWidget { const AdminLoginScreen({super.key}); @override State<AdminLoginScreen> createState() => _AdminLoginScreenState(); }
class _AdminLoginScreenState extends State<AdminLoginScreen> {
 final email=TextEditingController(), password=TextEditingController(); bool busy=false, hidden=true; String? error;
 @override void dispose(){email.dispose();password.dispose();super.dispose();}
 Future<void> signIn() async { if(email.text.trim().isEmpty||password.text.isEmpty){setState(()=>error='أدخل البريد الإلكتروني وكلمة المرور');return;} setState(()=>{busy=true,error=null}); try { await CloudConfig.client.auth.signInWithPassword(email:email.text.trim(),password:password.text); } catch(_){if(mounted)setState(()=>error='تعذر تسجيل الدخول. تحقق من بيانات الحساب وإعداد Supabase.');} finally {if(mounted)setState(()=>busy=false);} }
 @override Widget build(BuildContext context)=>Scaffold(body:Center(child:SingleChildScrollView(padding:const EdgeInsets.all(24),child:ConstrainedBox(constraints:const BoxConstraints(maxWidth:420),child:Card(child:Padding(padding:const EdgeInsets.all(22),child:Column(mainAxisSize:MainAxisSize.min,children:[const CircleAvatar(radius:34,child:Icon(Icons.storefront,size:34)),const SizedBox(height:16),const Text('دخول إدارة أسماك البركة',style:TextStyle(fontSize:21,fontWeight:FontWeight.bold)),const SizedBox(height:8),const Text('دخول خاص بمدير المتجر لمتابعة حجوزات الموقع.',textAlign:TextAlign.center),const SizedBox(height:20),TextField(controller:email,keyboardType:TextInputType.emailAddress,decoration:const InputDecoration(labelText:'البريد الإلكتروني',prefixIcon:Icon(Icons.email_outlined),border:OutlineInputBorder())),const SizedBox(height:12),TextField(controller:password,obscureText:hidden,onSubmitted:(_)=>signIn(),decoration:InputDecoration(labelText:'كلمة المرور',prefixIcon:const Icon(Icons.lock_outline),border:const OutlineInputBorder(),suffixIcon:IconButton(onPressed:()=>setState(()=>hidden=!hidden),icon:Icon(hidden?Icons.visibility:Icons.visibility_off)))),if(error!=null)Padding(padding:const EdgeInsets.only(top:12),child:Text(error!,style:const TextStyle(color:Colors.red),textAlign:TextAlign.center)),const SizedBox(height:18),SizedBox(width:double.infinity,child:FilledButton(onPressed:busy?null:signIn,child:busy?const CircularProgressIndicator():const Text('تسجيل الدخول'))),const SizedBox(height:12),const Text('يجب إنشاء حساب المدير وإضافته إلى جدول store_admins في Supabase أولاً.',style:TextStyle(fontSize:12,color:Colors.black54),textAlign:TextAlign.center)])))))))); }
}
